structlogger = structlog.get_logger()

_EVAL_RESULTS_DIR = Path("eval") / "results"
_SUMMARY_WIDTH = 70
_WIDE_SEP = "=" * _SUMMARY_WIDTH
_NARROW_SEP = "-" * _SUMMARY_WIDTH
_SUMMARY_JSON_FILENAME = "summary.json"
_SUMMARY_LOCK_FILENAME = ".summary.lock"
# Long enough to outlast a competing merge, short enough that a stale
# holder surfaces as an error rather than hanging the tool call.
_SUMMARY_LOCK_TIMEOUT_S = 30


class SimulationTurn(BaseModel):
    """A single turn in the simulated conversation."""

    model_config = ConfigDict(frozen=True)

    user: str
    bot: List[str]
    ttft_ms: Optional[float] = None
    turn_latency_ms: Optional[float] = None
    gaps_ms: List[float] = Field(default_factory=list)


class RunReport(BaseModel):
    """All data required to write a per-run result file."""

    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    scenario_name: str
    scenario_slug: str
    run_index: int
    timestamp: str
    conversation_id: str
    passed: bool
    turns: List[SimulationTurn]
    assertion_results: List[AssertionResult]
    criteria_results: List[CriterionResult]
    inspector_url: str
    error: Optional[str] = None
    # Whether `error` describes the harness (a timeout, a provider or
    # connection failure) or the agent's own behaviour. Set explicitly at the
    # point the exception is caught, because inferring it afterwards from the
    # message is how a silent agent gets reported as missing eval capacity.
    error_is_harness: bool = True
    judge_results: Optional[LlmJudgeResults] = None
    engine_tokens: Optional[Dict[str, Any]] = None
    duration_s: float = 0.0
    tool_scoring: Optional[ToolScoresPerConversation] = None
    observed_tools: Optional[List[ObservedTool]] = None
    expected_tools: Optional[List[Union[ExpectedTool, ExpectedToolGroup]]] = None
    tracker_events: Optional[str] = None
    evaluate_tool_calls: bool = False
    repair_occurrences: List[RepairOccurrence] = Field(default_factory=list)
    coval_run_id: Optional[str] = None
    coval_simulation_id: Optional[str] = None
    coval_metrics: Optional[List[Dict[str, Any]]] = None


class ScenarioSummaryEntry(BaseModel):
    """Per-scenario aggregated data for the experiment summary."""

    model_config = ConfigDict(frozen=True)

    scenario_name: str
    scenario_slug: str
    runs_passed: int
    runs_total: int
    # Runs that failed for harness reasons rather than on their merits
    # (timeout, cancellation, or an error raised mid-run). Included in
    # runs_total and counted as failures; tracked separately so a capacity
    # problem is not read as an agent defect.
    runs_errored: int = 0
    duration_s: float = 0.0


_TOOL_NAME_FIELD = "tool_name"
_BLOCK_ID_FIELD = "block_id"
_SKILL_ID_FIELD = "skill_id"
_ASSERTION_ID_FIELDS = ("flow_id", "flow_ids", "name", _SKILL_ID_FIELD)


def _dict_assertion_id(value: Dict[str, Any]) -> Optional[str]:
    """Extract the identifying string from a dict-valued assertion payload."""
    if _TOOL_NAME_FIELD in value:
        return str(value[_TOOL_NAME_FIELD])
    if _BLOCK_ID_FIELD in value:
        block_id = value[_BLOCK_ID_FIELD]
        skill_id = value.get(_SKILL_ID_FIELD)
        if skill_id:
            return f"{skill_id}/{block_id}"
        return str(block_id)
    id_val = next(
        (value[key] for key in _ASSERTION_ID_FIELDS if key in value),
        None,
    )
    if id_val is None:
        return None
    if isinstance(id_val, list):
        return ", ".join(str(item) for item in id_val)
    return str(id_val)


def _slot_part(item: Any) -> Optional[str]:
    """Return 'name' or 'name=repr(value)' for one slot dict entry, or None."""
    if not isinstance(item, dict) or "name" not in item:
        return None
    if "value" in item:
        return f"{item['name']}={item['value']!r}"
    return item["name"]


def _assertion_label(assertion: Dict[str, Any]) -> str:
    """Derive a short human-readable label from an assertion dict."""
    key = next(iter(assertion), None)
    if key is None:
        raise ValueError("assertion dict must not be empty")
    value = assertion[key]

    # e.g. action_executed: action_verify_identity
    if isinstance(value, str):
        return f"{key}({value})"

    # e.g. flow_completed: {flow_id: add_contact}
    if isinstance(value, dict):
        id_val = _dict_assertion_id(value)
        return f"{key}({id_val})" if id_val is not None else key

    # e.g. slot_was_set: [{name: contact_name, value: Alice}]
    if isinstance(value, list):
        parts = [p for item in value if (p := _slot_part(item)) is not None]
        return f"{key}({', '.join(parts)})" if parts else key

    return key


def _format_assertion_line(result: AssertionResult) -> str:
    """Format a single assertion result as a ``[PASS/FAIL] label`` line."""
    label = _assertion_label(result.assertion)
    status = "PASS" if result.passed else "FAIL"
    if result.detail:
        return f"[{status}] {label} — {result.detail}"
    return f"[{status}] {label}"


def _format_criterion_block(result: CriterionResult) -> str:
    """Format a criterion result as a two-line block with status and rationale."""
    status = "PASS" if result.passed else "FAIL"
    return f"[{status}] {result.criterion}\n  rationale: {result.reasoning}"


def _format_metrics_section(judge_results: LlmJudgeResults) -> List[str]:
    """Format the quality metrics block from a judge result."""
    lines: List[str] = []
    metrics = judge_results.metrics
    if metrics.error:
        lines.append(f"(judge error: {metrics.error})")
        return lines
    if not metrics.scale_metrics and not metrics.binary_metrics:
        lines.append("(no metrics scored)")
        return lines
    if judge_results.bot_quality is not None:
        lines.append(f"bot_quality: {judge_results.bot_quality}/5")
    for key, scale_result in metrics.scale_metrics.items():
        lines.append(f"  {key}: {scale_result.score}/5 — {scale_result.reasoning}")
    for key, bin_result in metrics.binary_metrics.items():
        status = "PASS" if bin_result.passed else "FAIL"
        lines.append(f"  {key}: {status} — {bin_result.reasoning}")
    if metrics.summary:
        lines.append(f"summary: {metrics.summary}")
    return lines


def _section(title: str) -> str:
    """Return a section header string."""
    return f"--- {title} ---"


def _mean_ms(values: List[Optional[float]]) -> Optional[float]:
    """Return the arithmetic mean of non-``None`` millisecond values."""
    recorded = [value for value in values if value is not None]
    if not recorded:
        return None
    return sum(recorded) / len(recorded)


def _format_latency_ms(value: Optional[float]) -> str:
    """Format a latency value for human-readable run reports."""
    if value is None:
        return "—"
    return f"{round(value)}ms"


def _binary_metric_passed(
    judge_results: Optional[LlmJudgeResults], metric_key: str
) -> Optional[bool]:
    """Return pass/fail for a binary judge metric, or ``None`` when unavailable."""
    if judge_results is None or judge_results.metrics.error:
        return None
    metric = judge_results.metrics.binary_metrics.get(metric_key)
    if metric is None:
        return None
    return metric.passed


def _latency_summary(turns: List[SimulationTurn]) -> Dict[str, Any]:
    """Build per-turn latency rows and conversation averages."""
    per_turn = [
        {
            "turn": index,
            "ttft_ms": turn.ttft_ms,
            "turn_latency_ms": turn.turn_latency_ms,
            "gaps_ms": turn.gaps_ms,
        }
        for index, turn in enumerate(turns, start=1)
    ]
    return {
        "per_turn": per_turn,
        "avg_ttft_ms": _mean_ms([turn.ttft_ms for turn in turns]),
        "avg_turn_latency_ms": _mean_ms([turn.turn_latency_ms for turn in turns]),
        "avg_gap_ms": _mean_ms([gap_ms for turn in turns for gap_ms in turn.gaps_ms]),
    }


def _indexed_pass_summary(items: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Run-level passed/total for indexed criteria or assertion rows."""
    total = len(items)
    passed_count = sum(1 for item in items if item.get("passed"))
    return {
        "passed": passed_count,
        "total": total,
        "all_passed": passed_count == total if total else False,
    }


def _criteria_comparison_metrics(report: RunReport) -> Dict[str, Any]:
    """Build eval-pass and per-criterion rows for cross-engine comparison."""
    criteria = [
        {
            "index": index,
            "criterion": result.criterion,
            "passed": result.passed,
        }
        for index, result in enumerate(report.criteria_results)
    ]
    block: Dict[str, Any] = {
        "eval_passed": report.passed,
        "criteria": criteria,
    }
    if criteria:
        block["criteria_summary"] = _indexed_pass_summary(criteria)
    if report.judge_results is not None and report.judge_results.criteria.error:
        block["criteria_error"] = report.judge_results.criteria.error
    return block


def _all_scale_metric_scores(
    judge_results: Optional[LlmJudgeResults],
) -> Dict[str, int]:
    """Return all 1–5 scale judge scores keyed by metric name."""
    if judge_results is None or judge_results.metrics.error:
        return {}
    return {
        key: metric.score for key, metric in judge_results.metrics.scale_metrics.items()
    }


def _assertion_comparison_metrics(report: RunReport) -> Dict[str, Any]:
    """Build per-assertion rows for cross-engine comparison."""
    if not report.assertion_results:
        return {}
    assertions = [
        {
            "index": index,
            "assertion": _assertion_label(result.assertion),
            "passed": result.passed,
        }
        for index, result in enumerate(report.assertion_results)
    ]
    return {
        "assertions": assertions,
        "assertions_summary": _indexed_pass_summary(assertions),
    }


def build_run_comparison_metrics(report: RunReport) -> Dict[str, Any]:
    """Structured latency and headline quality metrics for cross-engine comparison."""
    payload: Dict[str, Any] = {
        "scenario_slug": report.scenario_slug,
        "run_index": report.run_index,
        "timestamp": report.timestamp,
        "conversation_id": report.conversation_id,
        "latency": _latency_summary(report.turns),
        "task_completion": _binary_metric_passed(
            report.judge_results, "task_completion"
        ),
        **_criteria_comparison_metrics(report),
    }
    assertion_metrics = _assertion_comparison_metrics(report)
    if assertion_metrics:
        payload.update(assertion_metrics)
    if extended_eval_enabled():
        if report.coval_run_id:
            payload["coval_run_id"] = report.coval_run_id
        if report.coval_simulation_id:
            payload["coval_simulation_id"] = report.coval_simulation_id
        if report.coval_run_id and report.coval_simulation_id:
            payload["coval_results_url"] = coval_run_results_url(
                report.coval_run_id,
                report.coval_simulation_id,
            )
        if report.coval_metrics:
            payload["coval_metrics"] = report.coval_metrics
    scale_metrics = _all_scale_metric_scores(report.judge_results)
    if scale_metrics:
        payload["scale_metrics"] = scale_metrics
    if extended_eval_enabled() and report.engine_tokens is not None:
        payload["engine_tokens"] = report.engine_tokens
    return payload


def _format_latency_section(turns: List[SimulationTurn]) -> List[str]:
    """Format per-turn and conversation-average latency lines."""
    if not turns:
        return ["(no turns recorded)"]

    lines: List[str] = []
    for index, turn in enumerate(turns, start=1):
        line = (
            f"turn {index}: ttft={_format_latency_ms(turn.ttft_ms)}  "
            f"turn_latency={_format_latency_ms(turn.turn_latency_ms)}"
        )
        if turn.gaps_ms:
            formatted_gaps = ", ".join(
                _format_latency_ms(gap_ms) for gap_ms in turn.gaps_ms
            )
            line += f"  gaps={formatted_gaps}"
        lines.append(line)

    avg_ttft_ms = _mean_ms([turn.ttft_ms for turn in turns])
    avg_turn_latency_ms = _mean_ms([turn.turn_latency_ms for turn in turns])
    avg_gap_ms = _mean_ms([gap_ms for turn in turns for gap_ms in turn.gaps_ms])
    ttft_turn_count = sum(1 for turn in turns if turn.ttft_ms is not None)
    turn_latency_count = sum(1 for turn in turns if turn.turn_latency_ms is not None)
    gap_turn_count = sum(1 for turn in turns if turn.gaps_ms)

    summary_parts: List[str] = []
    if avg_ttft_ms is not None:
        summary_parts.append(f"ttft={_format_latency_ms(avg_ttft_ms)}")
    if avg_turn_latency_ms is not None:
        summary_parts.append(f"turn_latency={_format_latency_ms(avg_turn_latency_ms)}")
    if avg_gap_ms is not None:
        summary_parts.append(f"gap={_format_latency_ms(avg_gap_ms)}")
    if summary_parts:
        count_note = (
            f"over {ttft_turn_count} turns with bot text"
            if ttft_turn_count == turn_latency_count
            else (
                f"over {ttft_turn_count} turns with bot text, "
                f"{turn_latency_count} turns timed"
            )
        )
        # gap_ms is only present on a subset of turns (those with 2+ bot
        # messages), so its average has a different denominator than
        # ttft/turn_latency above — call that out explicitly rather than
        # letting the reader assume the same sample size.
        if avg_gap_ms is not None:
            count_note += f", {gap_turn_count} turns with a gap"
        lines.append(f"conversation avg: {'  '.join(summary_parts)}  ({count_note})")

    return lines


def _format_report_header(report: RunReport) -> List[str]:
    """Format the metadata header for a run report."""
    lines = [
        f"scenario: {report.scenario_name}",
        f"run: {report.run_index}",
        f"timestamp: {report.timestamp}",
        f"conversation_id: {report.conversation_id}",
    ]
    if extended_eval_enabled():
        if report.coval_run_id:
            lines.append(f"coval_run_id: {report.coval_run_id}")
        if report.coval_simulation_id:
            lines.append(f"coval_simulation_id: {report.coval_simulation_id}")
    lines.append(f"overall_result: {'PASS' if report.passed else 'FAIL'}")
    if report.error:
        lines.append(f"error: {report.error}")
    return lines


def _format_conversation_repair_section(report: RunReport) -> List[str]:
    """Format the conversation-repair section for a run report."""
    if not extended_eval_enabled():
        return []
    lines = format_conversation_repair_section(report.repair_occurrences)
    lines.append("")
    return lines


def _format_criteria_section(report: RunReport) -> List[str]:
    """Format the quality criteria section for a run report."""
    lines = [_section("Quality Criteria Results")]
    if report.criteria_results:
        for criterion in report.criteria_results:
            lines.append(_format_criterion_block(criterion))
            lines.append("")
    elif report.judge_results and report.judge_results.criteria.error:
        lines.append(f"(judge error: {report.judge_results.criteria.error})")
        lines.append("")
    else:
        lines.append("(none defined)")
        lines.append("")
    return lines


def _format_quality_metrics_section(report: RunReport) -> List[str]:
    """Format the quality metrics section for a run report."""
    lines = [_section("Quality Metrics")]
    if report.judge_results is not None:
        lines.extend(_format_metrics_section(report.judge_results))
    else:
        lines.append("(not evaluated)")
    lines.append("")
    return lines


def _format_tool_sections(
    report: RunReport,
) -> tuple[List[str], List[str]]:
    """Return tool-call metrics section lines and gated assertion lines."""
    if not report.evaluate_tool_calls or not extended_eval_enabled():
        return [], []

    observed = report.observed_tools or []
    metrics_lines, gate_lines = format_tool_scoring_report(
        report.tool_scoring,
        observed_tools=observed,
        expected_tools=report.expected_tools or [],
    )
    section_lines = [_section("Tool Call Metrics")]
    section_lines.extend(metrics_lines)
    section_lines.append("")
    return section_lines, gate_lines


def _format_assertion_results_section(
    report: RunReport, gate_lines: List[str]
) -> List[str]:
    """Format the assertion results section for a run report."""
    lines = [_section("Assertion Results")]
    assertion_lines: List[str] = []
    if report.assertion_results:
        assertion_lines.extend(
            _format_assertion_line(assertion) for assertion in report.assertion_results
        )
    if report.evaluate_tool_calls:
        assertion_lines.extend(gate_lines)
    if assertion_lines:
        lines.extend(assertion_lines)
    else:
        lines.append("(none defined)")
    lines.append("")
    return lines


def _format_transcript_section(turns: List[SimulationTurn]) -> List[str]:
    """Format the raw transcript section for a run report."""
    lines = [_section("Raw Transcript")]
    counter = 1
    for turn in turns:
        if turn.user.strip():
            lines.append(f"[{counter}] user: {turn.user}")
            counter += 1
        for msg in turn.bot:
            lines.append(f"[{counter}] agent: {msg}")
            counter += 1
    if not turns:
        lines.append("(no turns recorded)")
    lines.append("")
    return lines


def _format_coval_metric_line(metric: Dict[str, Any]) -> str:
    """Format one Coval metric output for the text report."""
    label = metric.get("metric_name") or metric.get("metric_id") or "unknown"
    value_text = format_coval_metric_value(
        metric.get("value"),
        metric_name=metric.get("metric_name"),
        metric_id=metric.get("metric_id"),
    )
    status = str(metric.get("status") or "").strip()
    if status and status.upper() not in {"COMPLETED"}:
        line = f"{label}: {value_text} (status={status})"
    else:
        line = f"{label}: {value_text}"
    explanation = metric.get("explanation")
    if explanation:
        line = f"{line} — {explanation}"
    return line


def _format_coval_metrics_section(report: RunReport) -> List[str]:
    """Format Coval-native metric outputs when present."""
    if not extended_eval_enabled() or not report.coval_metrics:
        return []
    lines = [_section("Coval Metrics")]
    for metric in report.coval_metrics:
        lines.append(_format_coval_metric_line(metric))
    lines.append("")
    return lines


def _format_report_trailer(report: RunReport) -> List[str]:
    """Format inspector URL, Coval results, additional metrics, and tracker events."""
    user_turns = sum(1 for turn in report.turns if turn.user.strip())
    lines = [
        _section("Inspector URL"),
        report.inspector_url,
        "",
    ]
    if extended_eval_enabled():
        if report.coval_run_id and report.coval_simulation_id:
            lines.extend(
                [
                    _section("Coval Results URL"),
                    coval_run_results_url(
                        report.coval_run_id, report.coval_simulation_id
                    ),
                    "",
                ]
            )
        lines.extend(_format_coval_metrics_section(report))
        lines.extend(
            [
                _section("Additional Metrics"),
                f"Turns to Completion: {user_turns}",
                "",
            ]
        )
    if report.tracker_events is not None:
        lines.append(_section("Tracker Events"))
        lines.append(report.tracker_events)
        lines.append("")
    return lines


def _format_run_report(report: RunReport) -> str:
    """Render a ``RunReport`` as a human-readable string."""
    tool_section_lines, gate_lines = _format_tool_sections(report)
    lines: List[str] = []
    lines.extend(_format_report_header(report))
    lines.append("")
    lines.extend(_format_conversation_repair_section(report))
    lines.extend(_format_criteria_section(report))
    lines.extend(_format_quality_metrics_section(report))
    lines.extend(tool_section_lines)
    lines.extend(_format_assertion_results_section(report, gate_lines))
    lines.extend(_format_transcript_section(report.turns))
    lines.append(_section("Latency"))
    lines.extend(_format_latency_section(report.turns))
    lines.append("")
    lines.extend(_format_report_trailer(report))
    return "\n".join(lines)


_UNSAFE_CHARS = frozenset('/\\<>:"|?*')


def safe_name(name: str) -> str:
    """Return ``name`` if it is a safe single path component, else raise."""
    if not name.strip() or name in (".", "..") or _UNSAFE_CHARS.intersection(name):
        raise ValueError(f"Unsafe path component: {name!r}")
    return name


def _load_accumulated_entries(
    experiment_dir: Path,
) -> Tuple[Dict[str, ScenarioSummaryEntry], float]:
    """Load accumulated entries and wall-clock seconds from the sidecar JSON.

    Returns empty state when the file does not exist or cannot be parsed.
    Using JSON instead of parsing summary.txt makes accumulation robust to
    scenario names that contain spaces or other characters.

    Accepts the older bare-list payload (entries only, no recorded wall clock)
    as well as the current object form.
    """
    json_path = experiment_dir / _SUMMARY_JSON_FILENAME
    try:
        payload = json.loads(json_path.read_text(encoding="utf-8"))
        if isinstance(payload, list):
            data, wall_clock_s = payload, 0.0
        else:
            data = payload["entries"]
            wall_clock_s = payload.get("wall_clock_s", 0.0)
        entries: Dict[str, ScenarioSummaryEntry] = {}
        for item in data:
            entry = ScenarioSummaryEntry(
                scenario_name=item["scenario_name"],
                scenario_slug=item.get("scenario_slug", item["scenario_name"]),
                runs_passed=item["runs_passed"],
                runs_total=item["runs_total"],
                runs_errored=item.get("runs_errored", 0),
                duration_s=item.get("duration_s", 0.0),
            )
            entries[entry.scenario_slug] = entry
        return entries, wall_clock_s
    except FileNotFoundError:
        return {}, 0.0
    except Exception:
        structlogger.warning(
            "artifact_writer.load_accumulated_entries.failed",
            event_info="summary.json unreadable; accumulated history will be lost.",
            path=str(json_path),
        )
        return {}, 0.0


def _save_accumulated_entries(
    experiment_dir: Path, entries: List[ScenarioSummaryEntry], wall_clock_s: float
) -> None:
    """Persist accumulated entries and wall-clock seconds to the sidecar JSON."""
    data = {
        "wall_clock_s": wall_clock_s,
        "entries": [
            {
                "scenario_name": e.scenario_name,
                "scenario_slug": e.scenario_slug,
                "runs_passed": e.runs_passed,
                "runs_total": e.runs_total,
                "runs_errored": e.runs_errored,
                "duration_s": e.duration_s,
            }
            for e in entries
        ],
    }
    (experiment_dir / _SUMMARY_JSON_FILENAME).write_text(
        json.dumps(data, indent=2), encoding="utf-8"
    )


def run_report_path(
    project_folder: Path,
    experiment_timestamp: str,
    scenario_slug: str,
    run_index: int,
) -> Path:
    """Return where a run's report file lives, without creating anything.

    Args:
        project_folder: Root directory of the Rasa project.
        experiment_timestamp: Experiment folder name.
        scenario_slug: Slug of the scenario the run belongs to.
        run_index: 1-based index of the run within that scenario.

    Returns:
        ``eval/results/<experiment_timestamp>/<scenario_slug>/run_<N>.txt``
    """
    return (
        project_folder
        / _EVAL_RESULTS_DIR
        / safe_name(experiment_timestamp)
        / safe_name(scenario_slug)
        / f"run_{run_index}.txt"
    )


def write_run_report(
    project_folder: Path, experiment_timestamp: str, report: RunReport
) -> Path:
    """Write the per-run result file and return its path.

    Path: ``eval/results/<experiment_timestamp>/<scenario_slug>/run_<N>.txt``
    """
    path = run_report_path(
        project_folder, experiment_timestamp, report.scenario_slug, report.run_index
    )
    scenario_dir = path.parent
    scenario_dir.mkdir(parents=True, exist_ok=True)
    path.write_text(_format_run_report(report), encoding="utf-8")
    json_path = scenario_dir / f"run_{report.run_index}.json"
    json_path.write_text(
        json.dumps(build_run_comparison_metrics(report), indent=2),
        encoding="utf-8",
    )
    return path


def write_run_audio(
    project_folder: Path,
    experiment_timestamp: str,
    scenario_slug: str,
    run_index: int,
    audio_bytes: bytes,
    *,
    extension: str = ".wav",
) -> Path:
    """Write the Coval simulation recording next to the run report files.

    Path: ``eval/results/<experiment_timestamp>/<scenario_slug>/run_<N><ext>``
    ``extension`` must include the leading dot and match Coval's served format
    (no re-encoding).
    """
    if not extension.startswith("."):
        raise ValueError(f"Audio extension must start with '.': {extension!r}")
    scenario_dir = (
        project_folder
        / _EVAL_RESULTS_DIR
        / safe_name(experiment_timestamp)
        / safe_name(scenario_slug)
    )
    scenario_dir.mkdir(parents=True, exist_ok=True)
    path = scenario_dir / f"run_{run_index}{extension}"
    path.write_bytes(audio_bytes)
    return path


def write_experiment_summary(
    project_folder: Path,
    experiment_timestamp: str,
    entries: List[ScenarioSummaryEntry],
    wall_clock_s: float = 0.0,
) -> Path:
    """Write ``eval/results/<experiment_timestamp>/summary.txt`` and return its path.

    Accumulation state is kept in a sidecar ``summary.json`` (machine-readable)
    so scenario names with spaces or special characters round-trip correctly.
    The human-readable ``summary.txt`` is always regenerated from the JSON state;
    provided entries win on name collision.

    Args:
        project_folder: Root directory of the Rasa project.
        experiment_timestamp: Experiment folder name.
        entries: Per-scenario results to merge into the accumulated state.
        wall_clock_s: Elapsed seconds this batch actually took. Reported
            separately from the per-scenario durations, which sum each
            scenario's runs and therefore measure total compute rather than
            elapsed time -- under concurrent execution the two diverge, and
            the summed figure alone would suggest parallelism had no effect.
            Accumulates across calls sharing one experiment_timestamp.
    """
    experiment_dir = (
        project_folder / _EVAL_RESULTS_DIR / safe_name(experiment_timestamp)
    )
    experiment_dir.mkdir(parents=True, exist_ok=True)

    # Accumulating across calls means load-merge-save, which is only atomic
    # while one process does it. Two MCP servers on the same project (a
    # standalone `rasa tools run` beside a builder-embedded one, or two editor
    # windows) interleave and silently drop whichever merge lands first. A
    # single coroutine cannot interleave with itself -- nothing awaits between
    # the load and the save -- so this guards processes, not tasks.
    with portalocker.Lock(
        experiment_dir / _SUMMARY_LOCK_FILENAME, "a", timeout=_SUMMARY_LOCK_TIMEOUT_S
    ):
        return _merge_and_write_summary(
            experiment_dir, experiment_timestamp, entries, wall_clock_s
        )


def _merge_and_write_summary(
    experiment_dir: Path,
    experiment_timestamp: str,
    entries: List[ScenarioSummaryEntry],
    wall_clock_s: float,
) -> Path:
    """Merge entries into the accumulated state and rewrite both summaries.

    Caller holds the experiment's summary lock.

    Args:
        experiment_dir: ``eval/results/<experiment_timestamp>/``.
        experiment_timestamp: Experiment folder name, for the result paths.
        entries: Per-scenario results to merge in; these win on collision.
        wall_clock_s: Elapsed seconds this batch took, added to the running total.

    Returns:
        Path to the regenerated ``summary.txt``.
    """
    accumulated, accumulated_wall_clock_s = _load_accumulated_entries(experiment_dir)
    for entry in entries:
        accumulated[entry.scenario_slug] = entry
    all_entries = list(accumulated.values())
    total_wall_clock_s = accumulated_wall_clock_s + wall_clock_s
    _save_accumulated_entries(experiment_dir, all_entries, total_wall_clock_s)

    total_runs = sum(e.runs_total for e in all_entries)
    total_passed = sum(e.runs_passed for e in all_entries)
    total_errored = sum(e.runs_errored for e in all_entries)
    total_duration_s = sum(e.duration_s for e in all_entries)

    lines: List[str] = [_WIDE_SEP, "EXPERIMENT SUMMARY", _WIDE_SEP]

    for entry in all_entries:
        status = "PASS" if entry.runs_passed == entry.runs_total else "FAIL"
        result_dir = (
            _EVAL_RESULTS_DIR / experiment_timestamp / safe_name(entry.scenario_slug)
        )
        lines.append(
            f"[{status}] {entry.scenario_name}"
            f"  {entry.runs_passed}/{entry.runs_total}"
            f"  {entry.duration_s:.1f}s"
            f"  {result_dir.as_posix()}"
        )

    lines.append(_NARROW_SEP)
    lines.append(f"Total: {total_passed}/{total_runs} passed")
    if total_errored:
        lines.append(
            f"       {total_errored} failed for harness reasons (timed out, "
            "cancelled, or errored); counted as failures above."
        )
    if total_wall_clock_s > 0:
        # Two different numbers: how long the experiment took, and how much
        # run time it contained. Under concurrency the run time is the larger
        # of the two, by roughly the parallelism used; across repeated calls
        # into one experiment the elapsed figure keeps accumulating while a
        # re-run scenario's time is replaced, so it can end up larger instead.
        # The second is named as a sum so the per-scenario times above, which
        # add up to it rather than to the wall clock, are not misread as
        # elapsed.
        lines.append(
            f"Time:  {total_wall_clock_s:.1f}s elapsed"
            f"  ({total_duration_s:.1f}s total run time)"
        )
    elif total_duration_s > 0:
        lines.append(f"Time:  {total_duration_s:.1f}s total run time")

    failing = [e for e in all_entries if e.runs_passed < e.runs_total]
    if failing:
        lines.append("")
        lines.append("Scenarios requiring attention:")
        for e in failing:
            pass_rate = e.runs_passed / e.runs_total if e.runs_total else 0
            incomplete = (
                f"  [{e.runs_errored} harness failures]" if e.runs_errored else ""
            )
            lines.append(
                f"  - {e.scenario_name}"
                f"  {e.runs_passed}/{e.runs_total} passed"
                f"  ({pass_rate:.0%}){incomplete}"
            )

    summary_txt = experiment_dir / "summary.txt"
    summary_txt.write_text("\n".join(lines), encoding="utf-8")
    return summary_txt
